-- A person's grade is dated: each grade applies from its from-date until a later from-date of the
-- person takes over. The first grade a person was given has no from-date: it applies from the
-- beginning of time. A person has at most one grade per from-date (and one with none).
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    from_date DATE,
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_grade_person ON person_grade (person_id);
INSERT INTO person_grade (person_id, from_date, grade) SELECT id, NULL, grade FROM person;
ALTER TABLE person DROP COLUMN grade;
-- Terms per grade: the days after its date a claim of a person of the grade is due by; a grade with
-- none here takes the sheet's terms.
CREATE TABLE grade_terms (
    sheet_id VARCHAR(100) NOT NULL,
    grade VARCHAR(20) NOT NULL,
    terms INT NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's due-by, fixed when it is created; claims already made take their date plus the sheet's
-- terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = c.sheet_id), c.claim_date);
UPDATE claim SET due_by = DATEADD(DAY, 14, claim_date) WHERE due_by IS NULL;
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- How many proofs a claim has. A claim whose due is above the sheet's proof threshold in force on its
-- date cannot be settled or approved while it has none. The threshold is a dated setting
-- (setting_value key 'proof-threshold'; blank: none).
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- The sheet's history: after each change that can move its figures, a revision of every claim,
-- person, rate and dated setting the change left different from its last revision (and of the
-- policy date), stamped with the sheet's today then. The sheet as it stood at the end of a day is
-- the last revision of each stamped on or before that day.
CREATE TABLE claim_revision (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_id       BIGINT         NOT NULL,
    recorded_on    DATE           NOT NULL,
    person_id      BIGINT         NOT NULL,
    amount         DECIMAL(14, 2) NOT NULL,
    claim_date     DATE           NOT NULL,
    status         VARCHAR(20)    NOT NULL,
    settled_due    DECIMAL(14, 2),
    stated         BOOLEAN        NOT NULL,
    stated_due     DECIMAL(14, 2),
    stated_na      BOOLEAN        NOT NULL,
    corrected_date DATE,
    due_by         DATE           NOT NULL,
    deferred_until DATE
);
CREATE INDEX claim_revision_sheet ON claim_revision (sheet_id, id);

-- A person's grades and holds are kept as text: each grade "from:grade" and each hold "from..to"
-- (a day left blank when there is none), separated by ";".
CREATE TABLE person_revision (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    person_id    BIGINT        NOT NULL,
    recorded_on  DATE          NOT NULL,
    name         VARCHAR(200)  NOT NULL,
    grades       VARCHAR(4000) NOT NULL,
    holds        VARCHAR(4000) NOT NULL,
    retired_from DATE,
    terms        INT
);
